import{_ as r}from"./chunks/2842a882d581006a9451.DapEtfkE.js";import{_ as t,C as o,o as i,c as n,j as e,a as s,E as l,a5 as h}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"来自一位正在康复的无神论者的信息（如何找到上帝）","description":"","frontmatter":{"title":"来自一位正在康复的无神论者的信息（如何找到上帝）","originalTitle":"A Message From A Recovering Atheist (How To Find God)","date":"2023-02-03","originalUrl":"https://thedankoe.com/letters/a-message-from-a-recovering-atheist-how-to-find-god/","minutes":12,"sourceHash":"62399d054661619c389b0f650533da1042a886c8fcb1ec264fc3d39e33337272","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/a-message-from-a-recovering-atheist-how-to-find-god/"}]]},"headers":[],"relativePath":"letters/a-message-from-a-recovering-atheist-how-to-find-god.md","filePath":"letters/a-message-from-a-recovering-atheist-how-to-find-god.md"}'),d={name:"letters/a-message-from-a-recovering-atheist-how-to-find-god.md"};function c(m,p,f,g,u,b){const a=o("ArticleMeta");return i(),n("div",null,[p[0]||(p[0]=e("h1",{id:"来自一位正在康复的无神论者的信息-如何找到上帝",tabindex:"-1"},[s("来自一位正在康复的无神论者的信息（如何找到上帝） "),e("a",{class:"header-anchor",href:"#来自一位正在康复的无神论者的信息-如何找到上帝","aria-label":'Permalink to "来自一位正在康复的无神论者的信息（如何找到上帝）"'},"​")],-1)),l(a),p[1]||(p[1]=h('<p>很长一段时间以来，我一直都在逃避写这封信。</p><p>我从未觉得自己“准备好了”，现在也依然如此，但我知道写下来有助于理清我的思路。</p><p>我希望这些思考能对你有所裨益。</p><p>宗教和政治很像，当人们不同意你的观点时，他们会产生一种无意识的情绪反应，喷出他们从出生起就被灌输的、预先编排好的话术。</p><p>更糟的是，宗教和政治为不确定的未来带来了确定性。从心理学的角度来看，这就是为什么人们把自由思考外包给这些意识形态结构；为了让大脑井然有序，并防止陷入混乱。</p><p>当一个人的观点受到威胁时，他们会产生一种生理上的求生反应，就像被蛇死死缠住的老鼠一样。</p><p>于是，他们像往常一样强化自己的身份，将自己对真理封闭起来（这很讽刺），并且永远不会把思想开放到前理性发展阶段（pre-rational stage）之上。</p><p>我鼓励你在读这封信时保持开放的心态，如果你做不到，请取消订阅。我不是要求你接受我的信仰，我是要求你挑战你自己的信仰。</p><p>我从小就是一名“后期圣徒”（Latter-Day Saint），有些人把这种意识形态称为“摩门教”（Mormonism）。</p><p>每个星期天，我都会穿上黑西裤、纯白衬衫，打上我爸送我的那条我最喜欢的领带。</p><p>这从主日学开始，12岁以下的孩子会唱《我是神的孩子》（I Am A Child Of God）等赞美诗，然后开始学习《圣经》或《摩门经》的课程。</p><p>12岁时，男孩们成为了执事。14岁时成为教师。16岁时成为祭司。所有这些在神职中的责任都在不断增加。</p><p>我们去圣殿旅行，为死者进行洗礼，并参加“神学院”；那是在被送去公立学校之前的一个小时的宗教学习。</p><p>我在教会有过非常棒的经历，比如童子军以及与之相关的为期一周的跨季节探险。在这个信仰体系中有很多不可思议的人，但我总是抱有怀疑态度。</p><p>当你毫无畏惧地去质疑这些教义时，它们在逻辑、科学或现实层面上根本说不通。</p><p>在教会期间，我很庆幸能够接触到互联网。</p><p>我让好奇心驱使我掉进基督教、天主教、穆斯林甚至无神论意识形态的兔子洞，这样我就能了解它们到底是怎么回事。</p><p>星期天，我和高中朋友们去他们各自的教堂，保持开放的心态，观察并提出质疑。</p><p>我能注意到其中的规律，但它们仍然缺乏合理性。在当时，我无法接受对我提出的每一个哲学问题都给出同样千篇一律的回答：</p><p>“只要有信仰就好。”</p><p>不知怎的，我知道一辈子抱着相同的信仰对我来说没有什么好处。</p><p>在过去十年里观察我以前的教友们（感谢Facebook），证明我是对的。</p><h2 id="自我发展与前理性-超理性谬误" tabindex="-1">自我发展与前理性／超理性谬误 <a class="header-anchor" href="#自我发展与前理性-超理性谬误" aria-label="Permalink to &quot;自我发展与前理性／超理性谬误&quot;">​</a></h2><p>有神论者、无神论者和唯灵论者（按此顺序）之间的区别在于自我发展。</p><p>在本信的其余部分，请将“自身（self）”和“自我（ego）”视为同义词。</p><p>你并没有摆脱你的自我，你是在发展它，直到它与现实融为一体。</p><p>你不能通过试图回答“我是谁？”这个不可能回答的问题来发展自我，而是要问“我不是谁？”，直到你除了纯粹的意识之外什么都不剩。</p><p>在我探寻意义的过程中，我遇到了三个令人难以置信的资源：</p><ul><li>简·卢文格（Susan Cook Greuter）的《自我发展的9个阶段》（The 9 Stages Of Ego Development），由 Actualized.Org 总结（<a href="https://youtu.be/J3hNosyyXRA" target="_blank" rel="noreferrer">链接</a>）</li><li>肯·威尔伯（Ken Wilber）的人类意识进化 AQAL 模型</li><li>个人、组织和社会的螺旋动力学（Spiral Dynamics）进化模型</li></ul><p>这些都是用于绘制个体和集体心理发展图谱的模型。</p><p>一封信里能提炼的东西实在有限，所以我鼓励你在自己的时间里去探索它们。</p><p>但是，肯·威尔伯的一个模型有助于解释精神发展的各个阶段。</p><p>它被称为前/超谬误（Pre-Trans Fallacy）。</p><p>简而言之，你可以把它想象成去年很火的那个钟形曲线梗图：</p><p><img src="'+r+'" alt=""></p><p>如果你在寻找意义、理解和上帝的过程中迷失了方向，这个模型可以帮到你。</p><p>前/超谬误不仅适用于宗教。它适用于任何领域的发展。</p><p>它指出人们经常把发展的前理性阶段（pre-rational stage）误认为是后理性阶段（post-rational），因为两者都不代表理性阶段（rational stage）。</p><p>我们以宗教为例，说明这个概念最简单的方法就是对上帝的信仰。</p><p>圣经主义基督徒对上帝的概念与神秘主义者对上帝的概念截然不同。</p><p>从外面看，他们似乎在说同样的事情，因为他们都不是无神论者。</p><p>他们是不一样的，让我们来剖析一下原因：</p><h3 id="前理性阶段" tabindex="-1">前理性阶段 <a class="header-anchor" href="#前理性阶段" aria-label="Permalink to &quot;前理性阶段&quot;">​</a></h3><p>在这封信中，我们将使用基督教作为例子，因为这是我在其最极端形式下所经历过的。</p><p>但是，这可以应用于任何意识形态，无论是否是宗教的。</p><p>我看到这些模式也反映在商业中。</p><p>就像互联网上的某些圈层相信存在一种“最好”的获客、内容或品牌策略，并且没有任何改进的空间。</p><p>实际上，发展最完善的个体会吸取这些原则，经历各个阶段，并创造出自己的方法，以看到任何领域所指向的理想最终结果。对商业来说是金钱，对宗教来说是意义，对健康来说是健康。</p><p>如果不去质疑你自己的信念，你就会把自己同新发现、新创新，以及那些能为你的人生和世界带来真正进步的事物隔绝开来。</p><p>处于这种前理性阶段的个体、组织和社会，最贴切的描述就是“狂热的宗教分子（bible thumpers）”。</p><p>这个阶段的精神属性是高度物质化的。</p><p>他们认为天堂和地狱是字面意义上的地方，在那里“你”（这只是一个概念，即自我）会得到处女的赐福或是遭受烈火的折磨。</p><p>任何形式的反馈都被视为一种威胁。</p><p>他们用从被灌输进那个信仰体系以来就一直鹦鹉学舌重复的同样的话语进行反击。</p><p>真正的问题在于，处于这个阶段的人对更高阶段的发展封闭了他们的思想。</p><p>他们无法客观地看待和解读现实的本来面目。</p><p>注：我并不打算将任何宗教意识形态描绘成坏的。通过研究可以发现深刻的真理。问题在于，人们认为这些真理仅局限于一种理解这些真理的视角。</p><h3 id="理性阶段" tabindex="-1">理性阶段 <a class="header-anchor" href="#理性阶段" aria-label="Permalink to &quot;理性阶段&quot;">​</a></h3><p>理性阶段是我非常熟悉的阶段。</p><p>它是刻板印象中的无神论者，拒绝任何关于更高力量的概念。</p><p>他们依赖科学发现来证明什么是真实的，什么是虚假的。在这个阶段看来，如果不能被科学证明，那就不是真实的。</p><p>这是一个虚假怀疑主义开始占据主导的阶段。</p><p>无神论者理所应当地“质疑一切”，但却没有质疑他们自己的信仰。相反，他们囤积了大量具有辩论价值的信息来反驳上帝的存在。</p><p>他们能看穿前理性阶段明显的缺陷，但却没有敞开心扉去正视自身的缺陷。他们自以为已经正视了，而这恰恰阻碍了他们走向更深处。</p><p>这里需要明白的一点是，大多数人都会经历这3个发展阶段。</p><p>如果你处于理性或前理性阶段，你不会立刻跃迁到下一个阶段。这需要时间和自我的发展。</p><h3 id="超理性阶段" tabindex="-1">超理性阶段 <a class="header-anchor" href="#超理性阶段" aria-label="Permalink to &quot;超理性阶段&quot;">​</a></h3><p>在超理性阶段，对上帝的信仰回归了，但这不再是一个天上男人的静态形象。</p><p>这就是东方哲学、神秘主义以及与灵性相关的标签发挥作用的地方。</p><p>我不想委屈了这个阶段，因为对于那些缺乏高层次理解心智能力的人来说，这很难解释（这绝不是一种侮辱，我也不认为处于这个阶段的人在地位上“高于”其他人，这与地位无关）。</p><p>相反，我将试着指出上帝的所在。我鼓励你把这作为一种方式，去注意和理解你日常生活中存在的这种更高层次的力量。</p><h2 id="如何找到上帝" tabindex="-1">如何找到上帝 <a class="header-anchor" href="#如何找到上帝" aria-label="Permalink to &quot;如何找到上帝&quot;">​</a></h2><blockquote><p>了解自己的人就了解上帝。——亚历山大的革利免（Clement Of Alexandria）</p></blockquote><p>首先，让我们区分一下“概念”和“现实”。</p><p>概念是我们对现实中某个层面的标签，我们在脑海中将其视为静态。</p><p>它们很有用，但不是定律。现实像河流一样流动，而概念则是那条河流的一张快照。</p><p>这就引入了佛教的<em>无常</em>（impermanence）原则。</p><p>也就是说，没有任何事物能被大脑孤立并保持静态。一种想法、观念、概念、意识形态、人、物品、社区、情感，以及任何我们用大脑处理并期望它保持不变的东西都不行。</p><p>举个例子，我们如何解释我们所看到的，是由我们当时的视角决定的，而我们的视角又受我们心境的影响。</p><p>自我使得这个问题永恒存在。它不想改变。</p><p>如果我很生气，对商业也知之甚少，而我看到一位亿万富翁发了一篇关于钱的帖子……你能猜到结果。</p><p>我会在脑海中形成一个概念，认定那个亿万富翁是个什么样的人（在只读了他们<em>一篇</em>帖子之后），并用我自己的信念来巩固这个概念。</p><p>“他有对有钱的父母。”</p><p>“他只是走运罢了，我永远做不到。”</p><p>“他为什么不把钱捐给慈善机构？他的钱难道还不够多吗？”</p><p>即使你嘴上不说这些话，你的自我也会说。</p><p>自我制造了障碍、限制和编造的故事来掩盖现实。它试图为你脑海中构建的静态图像填补空白，从而阻碍你看清事物的本来面目。</p><p>实际上，你根据一篇仅占他人一生贡献0.0000000000001%的帖子，就形成了对这个人的完整看法。</p><p><em>每个人都有获得自由的渴望，这很重要。</em></p><p>有人会说，这是更高力量的内心声音。</p><p>就心智而言，所有的自由只不过是通过采取更高的视角而带来的障碍消解。</p><p>当你采取更高的视角时，你就能开始看清事物的本来面目。</p><p>这是所有精神教诲的经验。</p><h3 id="上帝的模式" tabindex="-1">上帝的模式 <a class="header-anchor" href="#上帝的模式" aria-label="Permalink to &quot;上帝的模式&quot;">​</a></h3><p>圣力（Teotl）、梵（Brahman）、无限、本源、宇宙等等，都是看待上帝的视角。</p><p>阿兹特克哲学中的圣力（Teotl）被定义为“一种单一的、赋有生机的、永远自我产生和自我再生的神圣力量、能量或原动力”。</p><p>简而言之，这就是“精神”。</p><p>佛教中的梵（Brahman）被定义为，“所有现象背后的终极现实……梵是无形的，但它是可见现实中所有形态的诞生地。”</p><p>无限（Infinity）或本源（Source），是那些选择以这种方式去理解上帝的人所使用的其他常见视角。</p><p>它们都指向同一个东西，而这个东西无法被捕获并孤立成一种宗教意识形态。</p><p>我的意思是……它可以被孤立，也确实曾经被孤立过，但随着上个世纪人们的思想慢慢开始开放，这些建构已经受到了质疑，这是有充分理由的。</p><h3 id="宇宙" tabindex="-1">宇宙 <a class="header-anchor" href="#宇宙" aria-label="Permalink to &quot;宇宙&quot;">​</a></h3><p>我最喜欢通过宇宙的视角来诠释这种无形的力量。</p><p>Universe（宇宙）= uni-verse = one-song（同一首赞歌）。</p><p>一首无尽的歌，有着高潮与低谷、多种乐器的和声、情节的推进、顶点、回落以及副歌。</p><p>这种模式也反映在人类的意义建构之中。</p><p>人类通过故事来理解世界，而我们之所以对游戏着迷，是因为它们是带有互动挑战的故事，能让我们的注意力高度集中。</p><p>问题在于，我们总是试图孤立地去理解某个音符、某句歌词、某种乐器或某位音乐家，而毫不顾及全局。</p><p>如果你把故事的一部分剥离出来，尤其是负面的那部分，你会过得很糟糕。除非你拉开视角，去看整个故事如何在你的眼前展开。</p><p>让我们来过一遍雨的自我生成与自我再生的故事：</p><p>想象一片海洋或一片巨大的水域。太阳的热量蒸发了这些水，将其分裂成无数微小的水滴。</p><p>这些水滴上升并重新聚集成云。这些云体积变大，又进一步汇合成更大的云。</p><p>很快，水滴在云层中不断聚集，直到它们重得足以化作雨水落回大地。</p><p>雨水积成水洼，汇入溪流，并流经其他的生态过程。</p><p>最终，随着时间的推移，雨水一路流回海洋，这个过程又重新开始。</p><p>这绝不仅是一个关于分裂与融合的局部现象。</p><p><strong>它是无限的。</strong></p><p>你脑海中的想法分裂又重组，我们称之为创造力。</p><p>纵观人类历史，种族曾经分裂，而现在正在重新融合。</p><p>从宇宙的视角来看，你对此的看法并不重要，我的也一样。</p><p>种族的壁垒不断受到质疑和抗争，直到人们能够与任何他们喜欢的人结合。当然，这并不是这一切背后的主要驱动力。</p><p>在未来的某个时候，我们所有人的皮肤可能都会变成人类眼中相同深浅的微棕色，而“种族”作为一个概念将会坍塌并融为一体。</p><p>你人生中的各个篇章又如何呢？你经历过高潮与低谷。你结交过朋友，也失去过朋友。你已经改变了，即便你的头脑依然执念于那个过去的自己。</p><p>我鼓励你在任何地方都去留心这些模式，即使是在做早餐、写书或上厕所时。</p><p>这就是你在日常生活中寻得上帝（God）的方式。透过表面看本质，去欣赏那些机械的、预设的行动背后的深意（是的，那些机械行动可能正在赞美一个停留在表象的上帝形象，这似乎完全背离了初衷）。</p><p>去关注局部、整体，关注它们如何在这个物质地球上共舞，并如何在集体意识中激荡出涟漪。</p><h3 id="上帝的实用性" tabindex="-1">上帝的实用性 <a class="header-anchor" href="#上帝的实用性" aria-label="Permalink to &quot;上帝的实用性&quot;">​</a></h3><p>你大概会问：“这究竟对我的生活有什么实际用处？”</p><p>第一，因为这不是“你”的生活。</p><p>这无关乎你自私且狭隘的视角。你注定要拓宽你的思维，超越这些局限。</p><p>第二，难道这不让你着迷吗？你所认为的那些平淡无奇、“正常”的行动背后的深意？</p><p>在物质、地位和言辞的表象之下，还有更广阔的天地。</p><p>你是某个更为宏大的存在的一部分，而这只能通过灵性去察觉。</p><p>这样做会揭示出，我们如此珍视的那些概念、信念和理想，并非是一成不变的。</p><p>当我们认同这些由大脑构建出的实体，并把它们视作永恒不变时，我们就会陷入无尽的情感内耗中，从而阻碍个人和集体的进步。</p><p>思想开阔的人顺应宇宙流动，而思想封闭的人则试图强迫宇宙顺应他们。</p><p>如果思想封闭的人是阻挡真正进步的壁垒，那么思想开阔的人就有责任提升他们。</p><p>你能养成的最有益的习惯之一，就是玩“思维乐高”。</p><p>和某个观念、想法或问题待在一起，顺着自然显现的线索去追寻它们之间的联系。</p><p>对小我（egoic）带来的分心保持警惕。</p><p>这就是你如何在没有任何外部工具或指导的情况下，练习创造力、正念和深度思考的方法。</p><p>在文化、社会和个人的存在层面上，一个巨大的问题就是对意识形态的认同。</p><p>人类将各种想法组合成所谓的、不可分割的思想统一体。</p><p>我们没有为分裂和重组留下任何空间。我们没有为上帝留下任何空间。</p><p>– Dan Koe</p><h3 id="当你准备好时-我可以通过以下方式帮助你" tabindex="-1">当你准备好时，我可以通过以下方式帮助你 <a class="header-anchor" href="#当你准备好时-我可以通过以下方式帮助你" aria-label="Permalink to &quot;当你准备好时，我可以通过以下方式帮助你&quot;">​</a></h3><p>第一期单人创业冲刺营（Solopreneur Sprints）将在 3 天后开始。如果你想为你的一人企业打好基础，学习撰写 20 多篇基础内容，并确切了解如何实现可持续增长，去看看吧。</p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">点击此处以 150 美元报名。</a></p><p>如果你想学习一项抗衰退的技能，让你能做自由职业者、找到社交媒体工作或为自己建立名声，那么去学习具有高影响力、说服力的写作吧。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">报名加入 2 Hour Writer（两小时写手）。</a></p><p>如果你渴望一个志同道合的社群，以及一个包含 200 多种商业、健康和表现策略的资料库，去看看 Modern Mastery 吧。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需 5 美元即可加入。</a></p><hr><p><a href="/en/letters/a-message-from-a-recovering-atheist-how-to-find-god">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',154))])}const A=t(d,[["render",c]]);export{q as __pageData,A as default};
